    see: ['saw', 'seen', 'sees', 'seeing'],
    take: ['took', 'taken', 'takes', 'taking'],
    get: ['got', 'gets', 'getting'],
    make: ['made', 'makes', 'making'],
    do: ['did', 'does'],
    hit: ['hits', 'hitting'],
