    speak: ['spoke', 'speaks', 'speaking'],
    give: ['gave', 'given', 'gives', 'giving'],
    put: ['puts', 'putting'],
    sit: ['sat', 'sits', 'sitting'],
    sneak: ['snuck', 'sneaked', 'sneaks', 'sneaking'],
