// Study pack downloads hub: the road kit. Printables open as their own A4 sheets (#study/n3, #study/padkos).
const DL_G = "'Switzer', 'Helvetica Neue', Arial, sans-serif",
  DL_M = "'IBM Plex Mono', monospace";
const DL = {
  blue: (window.LSD_PAL || {}).blue || '#0a63ff',
  hl: (window.LSD_PAL || {}).hl || '#cde0fb',
  ink: '#111111',
  paper: (window.LSD_PAL || {}).paper || '#efefed',
  muted: '#6e6e73'
};
const DL_WALL_WORDS = ['Aweh', 'Kiff', 'Shot', 'Vy', 'Smaak', 'Bru'];
function dlMono(ctx, t, x, y, sz, col, al = 'left') {
  ctx.font = `500 ${sz}px ${DL_M}`;
  ctx.fillStyle = col;
  ctx.textAlign = al;
  ctx.letterSpacing = '2px';
  ctx.fillText(t.toUpperCase(), x, y);
  ctx.letterSpacing = '0px';
  ctx.textAlign = 'left';
}
function dlWrap(ctx, text, max) {
  const out = [];
  let cur = '';
  text.split(' ').forEach(w => {
    const t = cur ? cur + ' ' + w : w;
    if (cur && ctx.measureText(t).width > max) {
      out.push(cur);
      cur = w;
    } else cur = t;
  });
  out.push(cur);
  return out;
}
function dlSave(canvas, name) {
  return new Promise(res => canvas.toBlob(b => {
    const u = URL.createObjectURL(b);
    const a = document.createElement('a');
    a.href = u;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(u), 4000);
    res();
  }, 'image/png'));
}
const dlFonts = () => Promise.all(['800 120px Switzer', '600 40px Switzer', "500 24px 'IBM Plex Mono'"].map(f => document.fonts.load(f))).catch(() => {});

// Teams backgrounds, 1920 × 1080. Text sits in the corners: your head goes in the middle.
function dlTeams(kind, logo) {
  const c = document.createElement('canvas');
  c.width = 1920;
  c.height = 1080;
  const ctx = c.getContext('2d');
  if (kind === 'beach') {
    const sky = ctx.createLinearGradient(0, 0, 0, 600);
    sky.addColorStop(0, '#f6f6f4');
    sky.addColorStop(1, (window.LSD_PAL || {}).sky || '#dfe9fb');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, 1920, 600);
    ctx.fillStyle = DL.blue;
    ctx.fillRect(0, 600, 1920, 230);
    ctx.fillStyle = (window.LSD_PAL || {}).sea || 'rgba(205,224,251,.55)';
    [630, 672, 720, 776].forEach((y, i) => ctx.fillRect(0, y, 1920, 3 + i));
    ctx.fillStyle = '#e8e3d7';
    ctx.fillRect(0, 830, 1920, 250);
    dlMono(ctx, 'Durban beachfront · 29.86° S, 31.02° E', 64, 1020, 22, DL.ink);
    dlMono(ctx, 'Learn to Speak Durban', 1856, 1020, 22, DL.ink, 'right');
  } else if (kind === 'gateway') {
    ctx.fillStyle = DL.paper;
    ctx.fillRect(0, 0, 1920, 1080);
    if (logo) {
      const lh = 150,
        lw = logo.width / logo.height * lh;
      ctx.drawImage(logo, 1920 - 72 - lw, 56, lw, lh);
    }
    ctx.font = `800 64px ${DL_G}`;
    ctx.letterSpacing = '-2px';
    ctx.fillStyle = DL.ink;
    ctx.fillText('Currently at Gateway, Durban.', 64, 980);
    ctx.letterSpacing = '0px';
    dlMono(ctx, 'Learn to Speak Durban. A public service by Gateway.', 64, 1030, 20, DL.muted);
  } else {
    ctx.fillStyle = DL.blue;
    ctx.fillRect(0, 0, 1920, 1080);
    dlMono(ctx, 'On leave soon, ekse', 1856, 1030, 22, '#fff', 'right');
  }
  return c;
}

// Phone wallpapers, 1080 × 1920. The word sits below the lock-screen clock.
function dlWall(word) {
  const L = window.LSD2.lessons,
    l = L.find(x => x.w === word) || L[0];
  const c = document.createElement('canvas');
  c.width = 1080;
  c.height = 1920;
  const ctx = c.getContext('2d');
  ctx.fillStyle = DL.blue;
  ctx.fillRect(0, 0, 1080, 1920);
  const X = 96,
    base = 1180;
  dlMono(ctx, 'Lesson ' + l.n + ' · ' + l.p, X, base - 250, 30, DL.hl);
  let fs = 230;
  ctx.font = `800 ${fs}px ${DL_G}`;
  ctx.letterSpacing = '-9px';
  while (ctx.measureText(l.w).width > 1080 - 2 * X - 20 && fs > 120) {
    fs -= 10;
    ctx.font = `800 ${fs}px ${DL_G}`;
  }
  const w = ctx.measureText(l.w).width,
    top = base - fs * 0.83,
    h = fs * 1.04;
  ctx.fillStyle = DL.hl;
  ctx.fillRect(X - 10, top, w + 26, h);
  ctx.fillStyle = '#fff';
  ctx.fillRect(X - 13, top, 6, h);
  ctx.fillRect(X + w + 13, top, 6, h);
  ctx.beginPath();
  ctx.arc(X - 10, top - 10, 13, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(X + w + 16, top + h + 10, 13, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = DL.ink;
  ctx.fillText(l.w, X, base);
  ctx.letterSpacing = '0px';
  ctx.font = `600 46px ${DL_G}`;
  ctx.fillStyle = '#fff';
  dlWrap(ctx, '— ' + l.d, 1080 - 2 * X).slice(0, 4).forEach((t, i) => ctx.fillText(t, X, base + 150 + i * 60));
  dlMono(ctx, 'Learn to Speak Durban', X, 1780, 24, '#fff');
  dlMono(ctx, 'A public service by Gateway', X, 1820, 24, DL.hl);
  return c;
}

