    exWall(x, w, h, Math.round(150 * k), 'rgba(17,17,17,.07)');
    dlMono(x, 'Learn to Speak Durban · all 50', w - 90 * k, h - 70 * k, Math.round(26 * k), DL.muted, 'right');
